fn fixture(name: &str) -> &'static str {
    FIXTURES.iter().find(|(n, _)| *n == name).unwrap().1
}

const SPACING: f32 = 0.125;
const DIMS: u32 = 66;
const ORIGIN: f32 = -4.125;
const FIELD_DIM: u32 = 17;
const FIELD_LO: f32 = -0.75;
const FIELD_SPACING: f32 = 1.5 / 16.0;
const RES: u32 = 4;
const ATLAS: (u32, u32) = (64, 16);
const MAX_STEPS: u32 = 256;
const MIN_STEP_FACTOR: f32 = 0.25;
const MARGIN: f32 = 0.5 * SPACING;
const STATUS_HIT: u32 = 1;

