/// A unit box ([-0.5, 0.5]^3) under `transform = T * R * S`.
struct Box3 {
    id: u32,
    transform: Mat4,
    mask: u8,
}

fn placed(id: u32, center: [f32; 3], scale: [f32; 3], rotation: Quat) -> Box3 {
    Box3 {
        id,
        transform: Mat4::from_scale_rotation_translation(
            Vec3::from(scale),
            rotation,
            Vec3::from(center),
        ),
        mask: 0x01,
    }
}

/// A closed room: interior [-3, 3]^3, walls 0.5 thick.
fn room() -> Vec<Box3> {
    let none = Quat::IDENTITY;
    vec![
        placed(100, [0.0, -3.25, 0.0], [7.0, 0.5, 7.0], none),
        placed(101, [0.0, 3.25, 0.0], [7.0, 0.5, 7.0], none),
        placed(102, [-3.25, 0.0, 0.0], [0.5, 7.0, 7.0], none),
        placed(103, [3.25, 0.0, 0.0], [0.5, 7.0, 7.0], none),
        placed(104, [0.0, 0.0, -3.25], [7.0, 7.0, 0.5], none),
        placed(105, [0.0, 0.0, 3.25], [7.0, 7.0, 0.5], none),
    ]
}

fn furnished() -> Vec<Box3> {
    let mut boxes = room();
    boxes.push(placed(
        200,
        [1.2, -2.0, 0.6],
        [1.0, 2.0, 0.8],
        Quat::from_rotation_y(35f32.to_radians()),
    ));
    boxes.push(placed(
        201,
        [-1.5, -2.5, -0.8],
        [1.0, 1.0, 1.0],
        Quat::from_rotation_x(20f32.to_radians()),
    ));
    boxes.push(placed(
        202,
        [-0.5, 1.2, 1.8],
        [1.6, 0.3, 0.6],
        Quat::from_axis_angle(Vec3::new(1.0, 1.0, 0.0).normalize(), 25f32.to_radians()),
    ));
    boxes
}

const PLATE_X: f32 = 0.0625;
const PLATE_THICKNESS: f32 = 0.02;
const PLATE_ID: u32 = 300;

/// The room split by a 0.02-thick plate between two voxel columns.
fn partitioned(plate_mask: u8) -> Vec<Box3> {
    let mut boxes = room();
    let mut plate = placed(
        PLATE_ID,
        [PLATE_X, 0.0, 0.0],
        [PLATE_THICKNESS, 7.0, 7.0],
        Quat::IDENTITY,
    );
    plate.mask = plate_mask;
    boxes.push(plate);
    boxes
}

fn box_sdf(p: Vec3) -> f32 {
    let q = p.abs() - Vec3::splat(0.5);
    q.max(Vec3::ZERO).length() + q.max_element().min(0.0)
}

fn axis_scales(m: &Mat4) -> Vec3 {
    Vec3::new(
        m.x_axis.xyz().length(),
        m.y_axis.xyz().length(),
        m.z_axis.xyz().length(),
    )
}

/// Faces in Card order: axis-major, + before -.
fn faces() -> impl Iterator<Item = (usize, f32)> {
    (0..3).flat_map(|a| [(a, 1.0), (a, -1.0)])
}

fn face_index(axis: usize, sign: f32) -> usize {
    axis * 2 + usize::from(sign < 0.0)
}

fn card_color(card: usize) -> [f32; 4] {
    let c = card as f32;
    [
        (c + 1.0) / 64.0,
        ((card * 7) % 64 + 1) as f32 / 64.0,
        ((card * 13) % 64 + 1) as f32 / 64.0,
        1.0,
    ]
}

#[derive(Clone, Copy, Debug)]
struct Expected {
    t: f32,
    instance: u32,
    normal: Vec3,
    card: usize,
    /// The entry lies within 1e-4 of an edge: face and Card are ambiguous.
    edge: bool,
}

/// CPU reference: nearest entering face of any box with `mask & ray.mask != 0`.
fn oracle(boxes: &[Box3], ray: &GpuRay) -> Option<Expected> {
    let origin = Vec3::from(ray.origin);
    let direction = Vec3::from(ray.direction);
    let mut best: Option<Expected> = None;
    for (index, b) in boxes.iter().enumerate() {
        if u32::from(b.mask) & ray.mask[0] == 0 {
            continue;
        }
        let inverse = b.transform.inverse();
        let o = inverse.transform_point3(origin);
        let d = inverse.transform_vector3(direction);
        let (mut near, mut far, mut axis, mut second) =
            (f32::NEG_INFINITY, f32::INFINITY, 0, f32::NEG_INFINITY);
        let mut inside = true;
        for a in 0..3 {
            if d[a].abs() < 1e-12 {
                inside &= o[a].abs() <= 0.5;
                continue;
            }
            let (t0, t1) = ((-0.5 - o[a]) / d[a], (0.5 - o[a]) / d[a]);
            let entry = t0.min(t1);
            if entry > near {
                second = near;
                near = entry;
                axis = a;
            } else if entry > second {
                second = entry;
            }
            far = far.min(t0.max(t1));
        }
        if !inside || near > far || near <= ray.t_min || near >= ray.t_max {
            continue;
        }
        if best.is_some_and(|e| e.t <= near) {
            continue;
        }
        let sign = -d[axis].signum();
        let mut local = Vec3::ZERO;
        local[axis] = sign;
        best = Some(Expected {
            t: near,
            instance: b.id,
            normal: b.transform.transform_vector3(local).normalize(),
            card: index * 6 + face_index(axis, sign),
            edge: (near - second).abs() <= 1e-4 * near.max(1.0),
        });
    }
    best
}

struct Scene {
    boxes: Vec<Box3>,
    instances: wgpu::Buffer,
    fields: wgpu::Buffer,
    bounds: wgpu::Buffer,
    grid: wgpu::Buffer,
    _composed_voxels: wgpu::Buffer,
    cards: wgpu::Buffer,
    card_lit: wgpu::Buffer,
    textures: Vec<wgpu::TextureView>,
    traversal_instances: wgpu::Buffer,
    face_normals: wgpu::Buffer,
    tlas: crate::acceleration::Tlas,
    /// `settings.z`: Card residency has pending (non-resident) instances.
    residency_pending: u32,
    source_expected: [u32; 4],
}

fn storage(gpu: &Gpu, label: &str, contents: &[u8]) -> wgpu::Buffer {
    gpu.device.create_buffer_init(&BufferInitDescriptor {
        label: Some(label),
        contents,
        usage: wgpu::BufferUsages::STORAGE,
    })
}

fn uniform(gpu: &Gpu, label: &str, contents: &[u8]) -> wgpu::Buffer {
    gpu.device.create_buffer_init(&BufferInitDescriptor {
        label: Some(label),
        contents,
        usage: wgpu::BufferUsages::UNIFORM,
    })
}

fn octahedral(n: Vec3) -> [f32; 2] {
    let p = n.xy() / (n.x.abs() + n.y.abs() + n.z.abs());
    if n.z >= 0.0 {
        return p.into();
    }
    let sign = |v: f32| if v >= 0.0 { 1.0 } else { -1.0 };
    [(1.0 - p.y.abs()) * sign(p.x), (1.0 - p.x.abs()) * sign(p.y)]
}

fn unit_box() -> ([[f32; 3]; 8], [u32; 36]) {
    let mut vertices = [[0.0; 3]; 8];
    for (i, v) in vertices.iter_mut().enumerate() {
        *v = [0, 1, 2].map(|a| if i >> a & 1 == 1 { 0.5 } else { -0.5 });
    }
    // Outward counter-clockwise quads per face (vertex bit a = +a).
    let quads: [[u32; 4]; 6] = [
        [1, 3, 7, 5],
        [0, 4, 6, 2],
        [2, 6, 7, 3],
        [0, 1, 5, 4],
        [4, 5, 7, 6],
        [0, 2, 3, 1],
    ];
    let mut indices = [0; 36];
    for (f, q) in quads.iter().enumerate() {
        indices[f * 6..f * 6 + 6].copy_from_slice(&[q[0], q[1], q[2], q[0], q[2], q[3]]);
    }
    (vertices, indices)
}

/// `pending` names instances whose Card rows are installed but not yet captured
/// (`ids.y = 2`, Card residency); any of them turns the residency flag on.
fn build_scene(
    gpu: &Gpu,
    canonical: &CanonicalParityScene,
    boxes: Vec<Box3>,
    pending: &[u32],
) -> Scene {
    let device = &gpu.device;
    let count = boxes.len() as u32;
    assert_eq!(canonical.instance_count, boxes.len());
    let voxel_count = (DIMS * DIMS * DIMS) as u64;
    let scene_instances = storage(gpu, "parity.instances", &canonical.instances);
    let scene_fields = storage(gpu, "parity.fields", &canonical.fields);
    let scene_bounds = storage(gpu, "parity.bounds", &canonical.bounds);
    let scene_grid = uniform(gpu, "parity.grid", &canonical.settings);
    let voxels = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("parity.voxels"),
        size: voxel_count * 16,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });

    // Cards: one per box face, one RES^2 atlas tile each, a distinct lit color per Card.
    let tiles_per_row = (ATLAS.0 / RES) as usize;
    assert!(boxes.len() * 6 <= tiles_per_row * (ATLAS.1 / RES) as usize);
    let texels = (ATLAS.0 * ATLAS.1) as usize;
    let mut cards = Vec::new();
    let mut card_lit = vec![[0f32; 4]; texels];
    let mut normal = vec![0i8; texels * 4];
    let mut f0 = vec![0u8; texels * 4];
    for b in &boxes {
        for (axis, sign) in faces() {
            let card = cards.len();
            let (u_axis, v_axis) = ((axis + 1) % 3, (axis + 2) % 3);
            let mut local = Vec3::ZERO;
            local[axis] = sign * 0.5;
            local[u_axis] = -0.5;
            local[v_axis] = -0.5;
            let along = |a: usize| {
                let mut e = Vec3::ZERO;
                e[a] = 1.0;
                b.transform.transform_vector3(e)
            };
            let (u, v) = (along(u_axis), along(v_axis));
            let n = (along(axis) * sign).normalize();
            cards.push(GpuCard {
                origin: b.transform.transform_point3(local).extend(1.0).into(),
                u: u.normalize().extend(u.length()).into(),
                v: v.normalize().extend(v.length()).into(),
                n: n.extend(1.0).into(),
                ids: [b.id, if pending.contains(&b.id) { 2 } else { 1 }, 0, 0],
            });
            let octa = octahedral(n).map(|c| (c * 127.0).round() as i8);
            let tile = (
                (card % tiles_per_row) * RES as usize,
                (card / tiles_per_row) * RES as usize,
            );
            for y in 0..RES as usize {
                for x in 0..RES as usize {
                    let texel = (tile.1 + y) * ATLAS.0 as usize + tile.0 + x;
                    card_lit[texel] = card_color(card);
                    normal[texel * 4..texel * 4 + 4]
                        .copy_from_slice(&[octa[0], octa[1], octa[0], octa[1]]);
                    f0[texel * 4 + 3] = 255;
                }
            }
        }
    }
    assert_eq!(canonical.card_owner_index.len(), cards.len() * 8);
    assert_eq!(
        cards.iter().map(|card| card.ids[0]).collect::<Vec<_>>(),
        canonical.card_owners
    );
    for (card, encoded) in cards
        .iter_mut()
        .zip(canonical.card_owner_index.chunks_exact(8))
    {
        card.ids[2] = u32::from_le_bytes(encoded[..4].try_into().unwrap());
        card.ids[3] = u32::from_le_bytes(encoded[4..].try_into().unwrap());
    }
    let texture = |label: &str, format: wgpu::TextureFormat, data: &[u8]| {
        device
            .create_texture_with_data(
                &gpu.queue,
                &wgpu::TextureDescriptor {
                    label: Some(label),
                    size: wgpu::Extent3d {
                        width: ATLAS.0,
                        height: ATLAS.1,
                        depth_or_array_layers: 1,
                    },
                    mip_level_count: 1,
                    sample_count: 1,
                    dimension: wgpu::TextureDimension::D2,
                    format,
                    usage: wgpu::TextureUsages::TEXTURE_BINDING,
                    view_formats: &[],
                },
                wgpu::util::TextureDataOrder::LayerMajor,
                data,
            )
            .create_view(&Default::default())
    };
    let zero = vec![0u8; texels * 4];
    let depth = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("parity.card-depth"),
        size: wgpu::Extent3d {
            width: ATLAS.0,
            height: ATLAS.1,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Depth32Float,
        usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::RENDER_ATTACHMENT,
        view_formats: &[],
    });
    let depth_view = depth.create_view(&Default::default());
    let textures = vec![
        texture("parity.albedo", wgpu::TextureFormat::Rgba8Unorm, &zero),
        texture(
            "parity.normal",
            wgpu::TextureFormat::Rgba8Snorm,
            bytemuck::cast_slice(&normal),
        ),
        texture("parity.emission", wgpu::TextureFormat::Rgba8Unorm, &zero),
        texture("parity.f0", wgpu::TextureFormat::Rgba8Unorm, &f0),
        depth_view,
    ];

    // Ray Query inputs: one BLAS for the unit box, one TLAS row per instance.
    let (vertices, indices) = unit_box();
    let face_normals: Vec<[f32; 4]> = indices
        .chunks_exact(3)
        .map(|t| {
            let p: Vec<Vec3> = t
                .iter()
                .map(|&i| Vec3::from(vertices[i as usize]))
                .collect();
            (p[1] - p[0])
                .cross(p[2] - p[0])
                .normalize()
                .extend(0.0)
                .into()
        })
        .collect();
    let vertex_buffer = device.create_buffer_init(&BufferInitDescriptor {
        label: Some("parity.box-vertices"),
        contents: bytemuck::cast_slice(&vertices),
        usage: wgpu::BufferUsages::BLAS_INPUT,
    });
    let index_buffer = device.create_buffer_init(&BufferInitDescriptor {
        label: Some("parity.box-indices"),
        contents: bytemuck::cast_slice(&indices),
        usage: wgpu::BufferUsages::BLAS_INPUT,
    });
    let blas = create_blas(
        device,
        &gpu.caps,
        &BlasDescriptor {
            label: Some("parity.box"),
            geometries: vec![TriangleGeometrySize {
                vertex_count: 8,
                index: Some((wgpu::IndexFormat::Uint32, 36)),
            }],
            preference: BuildPreference::FastTrace,
            update_mode: UpdateMode::Rebuild,
        },
    )
    .unwrap();
    let mut tlas = create_tlas(
        device,
        &gpu.caps,
        &TlasDescriptor {
            label: Some("parity.tlas"),
            max_instances: count,
            preference: BuildPreference::FastTrace,
            update_mode: UpdateMode::Rebuild,
        },
    )
    .unwrap();
    #[derive(serde::Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct QueryTableLayout {
        row_words: u32,
        mode_bits: u32,
    }
    // Produced beside the exact WGSL by the same TypeScript layout owner.
    let layout: QueryTableLayout = serde_json::from_str(include_str!(
        "__tests__/fixtures/world-traversal/ray-query-layout.json"
    ))
    .expect("invalid production query-table layout");
    assert_eq!(
        layout.row_words as usize,
        std::mem::size_of::<[u32; 4]>() / std::mem::size_of::<u32>()
    );
    let primitive_count = u32::try_from(indices.len() / 3).unwrap();
    let rows: Vec<[u32; 4]> =
        std::iter::once([0, 0, (count + 1).checked_mul(layout.row_words).unwrap(), 0])
            .chain(boxes.iter().map(|b| {
                [
                    b.id,
                    0,
                    primitive_count.checked_shl(layout.mode_bits).unwrap(),
                    0,
                ]
            }))
            .collect();
    let mut encoder = device.create_command_encoder(&Default::default());
    build_acceleration_structures(
        &mut encoder,
        &[BlasBuild {
            blas: &blas,
            geometries: vec![TriangleGeometry {
                vertex_buffer: &vertex_buffer,
                first_vertex: 0,
                vertex_stride: 12,
                index: Some((&index_buffer, 0)),
            }],
        }],
        &mut [TlasBuild {
            tlas: &mut tlas,
            instances: boxes
                .iter()
                .enumerate()
                .map(|(row, b)| {
                    let m = b.transform.transpose().to_cols_array();
                    TlasInstance {
                        blas: &blas,
                        // Rows of the column-major affine transform.
                        transform: std::array::from_fn(|k| m[k]),
                        custom_index: row as u32 + 1,
                        mask: b.mask,
                    }
                })
                .collect(),
        }],
    )
    .unwrap();
    // Card depth 0 = the face plane itself.
    drop(encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
        label: Some("parity.card-depth-clear"),
        color_attachments: &[],
        depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
            view: &textures[4],
            depth_ops: Some(wgpu::Operations {
                load: wgpu::LoadOp::Clear(0.0),
                store: wgpu::StoreOp::Store,
            }),
            stencil_ops: None,
        }),
        timestamp_writes: None,
        occlusion_query_set: None,
        multiview_mask: None,
    }));
    let compose = pipeline(gpu, fixture("compose.wgsl"));
    let bind = bind_group(
        gpu,
        &compose,
        &[
            (0, scene_instances.as_entire_binding()),
            (1, scene_fields.as_entire_binding()),
            (2, scene_bounds.as_entire_binding()),
            (3, scene_grid.as_entire_binding()),
            (4, voxels.as_entire_binding()),
        ],
    );
    {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&compose);
        pass.set_bind_group(0, Some(&bind), &[]);
        pass.dispatch_workgroups((voxel_count as u32).div_ceil(64), 1, 1);
    }
    gpu.queue.submit([encoder.finish()]);
    Scene {
        boxes,
        instances: scene_instances,
        fields: scene_fields,
        bounds: scene_bounds,
        grid: scene_grid,
        _composed_voxels: voxels,
        cards: device.create_buffer_init(&BufferInitDescriptor {
            label: Some("parity.cards"),
            contents: bytemuck::cast_slice(&cards),
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
        }),
        card_lit: storage(gpu, "parity.card-lit", bytemuck::cast_slice(&card_lit)),
        textures,
        traversal_instances: storage(
            gpu,
            "parity.traversal-instances",
            bytemuck::cast_slice(&rows),
        ),
        face_normals: storage(
            gpu,
            "parity.face-normals",
            bytemuck::cast_slice(&face_normals),
        ),
        tlas,
        residency_pending: u32::from(!pending.is_empty()),
        source_expected: canonical.source_expected,
    }
}

fn pipeline(gpu: &Gpu, source: &str) -> wgpu::ComputePipeline {
    let module = gpu
        .device
        .create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("parity"),
            source: wgpu::ShaderSource::Wgsl(source.into()),
        });
    gpu.device
        .create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("parity"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        })
}

fn bind_group(
    gpu: &Gpu,
    pipeline: &wgpu::ComputePipeline,
    entries: &[(u32, wgpu::BindingResource<'_>)],
) -> wgpu::BindGroup {
    let entries: Vec<_> = entries
        .iter()
        .map(|(binding, resource)| wgpu::BindGroupEntry {
            binding: *binding,
            resource: resource.clone(),
        })
        .collect();
    gpu.device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("parity"),
        layout: &pipeline.get_bind_group_layout(0),
        entries: &entries,
    })
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Traversal {
    GlobalSdf,
    RayQuery,
}

fn trace(gpu: &Gpu, scene: &Scene, traversal: Traversal, rays: &[GpuRay]) -> Vec<Traced> {
    let device = &gpu.device;
    let size = (rays.len() * std::mem::size_of::<Traced>()) as u64;
    let ray_buffer = storage(gpu, "parity.rays", bytemuck::cast_slice(rays));
    let output = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("parity.traced"),
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("parity.readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let parity = uniform(
        gpu,
        "parity.trace",
        bytemuck::bytes_of(&GpuParity {
            trace: [MARGIN, MIN_STEP_FACTOR, 0.0, 0.0],
            expected_source: scene.source_expected,
        }),
    );
    let settings = uniform(
        gpu,
        "parity.settings",
        bytemuck::bytes_of(&[
            scene.boxes.len() as u32 * 6,
            RES,
            scene.residency_pending,
            MAX_STEPS,
        ]),
    );
    let source = match traversal {
        Traversal::GlobalSdf => fixture("global-sdf.wgsl"),
        Traversal::RayQuery => fixture("ray-query.wgsl"),
    };
    let kernel = pipeline(gpu, source);
    let mut entries = match traversal {
        Traversal::GlobalSdf => vec![
            (1, scene.grid.as_entire_binding()),
            (2, scene.instances.as_entire_binding()),
            (3, scene.fields.as_entire_binding()),
            (4, scene.bounds.as_entire_binding()),
        ],
        Traversal::RayQuery => vec![
            (0, scene.tlas.binding()),
            (2, scene.traversal_instances.as_entire_binding()),
            (3, scene.face_normals.as_entire_binding()),
        ],
    };
    entries.extend([
        (5, scene.cards.as_entire_binding()),
        (6, scene.card_lit.as_entire_binding()),
        (7, ray_buffer.as_entire_binding()),
        (8, output.as_entire_binding()),
        (9, parity.as_entire_binding()),
        (10, settings.as_entire_binding()),
    ]);
    for (k, view) in scene.textures.iter().enumerate() {
        entries.push((11 + k as u32, wgpu::BindingResource::TextureView(view)));
    }
    let bind = bind_group(gpu, &kernel, &entries);
    let mut encoder = device.create_command_encoder(&Default::default());
    {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&kernel);
        pass.set_bind_group(0, Some(&bind), &[]);
        pass.dispatch_workgroups((rays.len() as u32).div_ceil(64), 1, 1);
    }
    encoder.copy_buffer_to_buffer(&output, 0, &readback, 0, size);
    gpu.queue.submit([encoder.finish()]);
    let (tx, rx) = mpsc::channel();
    readback.map_async(wgpu::MapMode::Read, .., move |result| {
        let _ = tx.send(result);
    });
    device.poll(wgpu::PollType::wait_indefinitely()).unwrap();
    rx.recv_timeout(Duration::from_secs(120)).unwrap().unwrap();
    let traced =
        bytemuck::cast_slice::<u8, Traced>(&readback.get_mapped_range(..).unwrap()).to_vec();
    readback.unmap();
    traced
}

fn fibonacci(count: usize) -> impl Iterator<Item = Vec3> {
    let golden = std::f32::consts::PI * (3.0 - 5f32.sqrt());
    (0..count).map(move |i| {
        let y = 1.0 - 2.0 * (i as f32 + 0.5) / count as f32;
        let r = (1.0 - y * y).sqrt();
        let phi = golden * i as f32;
        Vec3::new(r * phi.cos(), y, r * phi.sin())
    })
}

fn ray(origin: Vec3, direction: Vec3, mask: u32) -> GpuRay {
    GpuRay {
        origin: origin.into(),
        t_min: 0.0,
        direction: direction.into(),
        t_max: 20.0,
        mask: [mask, 0, 0, 0],
    }
}

/// Clearance of `p` from every box (a lower bound: local distance times the minimum scale).
fn clearance(boxes: &[Box3], p: Vec3) -> f32 {
    boxes
        .iter()
        .map(|b| {
            box_sdf(b.transform.inverse().transform_point3(p))
                * axis_scales(&b.transform).min_element()
        })
        .fold(f32::INFINITY, f32::min)
}

fn validation_scope(gpu: &Gpu) -> wgpu::ErrorScopeGuard {
    gpu.device.push_error_scope(wgpu::ErrorFilter::Validation)
}

fn assert_no_validation_error(scope: wgpu::ErrorScopeGuard) {
    if let Some(error) = pollster::block_on(scope.pop()) {
        panic!("wgpu validation error: {error}");
    }
}

fn close(a: [f32; 4], b: [f32; 4], tolerance: f32) -> bool {
    a.iter().zip(b).all(|(x, y)| (x - y).abs() <= tolerance)
}

fn percentile(values: &mut [f32], p: f32) -> f32 {
    if values.is_empty() {
        return f32::NAN;
    }
    values.sort_by(f32::total_cmp);
    values[((values.len() - 1) as f32 * p).round() as usize]
}

fn validate_world_bounds_control(control: &CanonicalHeaderControl) {
    let row = GpuBounds {
        lo: [-0.5, -0.5, -0.5, 0.0],
        hi: [0.5, 0.5, 0.5, 0.0],
        scale: [1.0; 4],
    };
    let scaled = GpuBounds {
        scale: [2.0, 3.0, 4.0, 2.0],
        ..row
    };
    assert_eq!(parity_sha256(&control.one), control.one_sha256);
    assert_eq!(parity_sha256(&control.two), control.two_sha256);
    let bytes = &control.two;
    let word =
        |index: usize| u32::from_le_bytes(bytes[index * 4..index * 4 + 4].try_into().unwrap());
    assert_eq!(bytes.len(), 192);
    assert_eq!(&bytes[..4], &[0x31, 0x50, 0x42, 0x57]);
    assert_eq!((word(1), word(2), word(3)), (1, 2, 2));
    assert_eq!((word(4), word(5)), (6, 6));
    assert_eq!((word(6), word(7), word(23)), (1, 0, 48));
    assert_eq!(f32::from_le_bytes(bytes[96..100].try_into().unwrap()), -0.5);
    assert_eq!(f32::from_le_bytes(bytes[176..180].try_into().unwrap()), 2.0);
    assert_eq!(
        &bytes[96..],
        bytemuck::cast_slice::<GpuBounds, u8>(&[row, scaled])
    );
    assert_eq!(control.one.len(), 144);
}

